/** A header that says a tool wrote the file: `@generated`, `autogenerated`, `DO NOT EDIT`. */
const GENERATED = /@generated|\bauto-?generated\b|\bdo not edit\b/i;

/**
 * Whether the first lines of a file say a tool wrote it (a pinned requirements file, a generated
 * client): a merge takes one side of it and the tool writes it again, so its lines are not compared.
 */
export function isGeneratedText(content: string): boolean {
  return GENERATED.test(content.split('\n', 10).join('\n'));
}
